class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

def segregate_even_odd(head):
    if not head or not head.next:
        return head

    even_head = None
    odd_tail = None
    current = head

    while current:
        if current.data % 2 == 0:
            if even_head is None:
                even_head = current
            else:
                odd_tail.next = current
                odd_tail = current
        else:
            if odd_tail is None:
                odd_tail = current
        current = current.next

    if odd_tail:
        odd_tail.next = None

    if even_head:
        even_tail = even_head
        while even_tail.next:
            even_tail = even_tail.next

        even_tail.next = odd_tail
    else:
        even_head = odd_tail

    return even_head
