        self.next = next

class Solution:
    def solve(self, head: ListNode) -> ListNode:
        if not head:
            return head

        even_head = head.next
        if not even_head:
            return head

        even = even_head
        odd = head

        while even and even.next:
            odd.next = even.next
            odd = odd.next
            even.next = odd.next
            even = even.next

        odd.next = even_head
        return head
